/* nd_psolk.c: NPSO2D, the pso table lookup of the combine decision. nd_pso_find takes the walker's NdCombIn and returns the table entry of
 * the description whose inputs equal it (nd_pso_in_eq), or 0. The table (nd_pso_tab.c, generated by gen_pso_main.c) holds nd_pso_dsc (the
 * descriptions by id), nd_pso_ord (the ids sorted by (cw0, cw1), equal keys in id order) and nd_pso_n. Binary search, no division. */
#include <stdint.h>
#include "ultra64.h"
#include "nd.h"
#include "nd_api.h"
#include "pm_gpu.h"

extern const NdPsoDesc nd_pso_dsc[]; /* nd_pso_tab.c */
extern const uint16_t nd_pso_ord[];  /* nd_pso_tab.c */
extern const unsigned nd_pso_n;      /* nd_pso_tab.c */

const NdPsoOut* nd_pso_find(const NdCombIn* w, unsigned vprim) {
    unsigned lo = 0, hi = nd_pso_n, m;
    while (lo < hi) { /* the lower bound of (w0, w1) in the sorted ids */
        m = (lo + hi) >> 1;
        const NdPsoDesc* d = &nd_pso_dsc[nd_pso_ord[m]];
        if (d->cw0 < w->w0 || (d->cw0 == w->w0 && d->cw1 < w->w1)) lo = m + 1;
        else hi = m;
    }
    for (m = lo; m < nd_pso_n; m++) {
        const NdPsoDesc* d = &nd_pso_dsc[nd_pso_ord[m]];
        if (d->cw0 != w->w0 || d->cw1 != w->w1) break;
        if (nd_pso_in_eq(d, w, vprim)) return nd_pso((NdPso)nd_pso_ord[m]);
    }
    return 0;
}
